def is_good_config(config, n):
    s = "".join(map(str, config))
    return s == "0" * n + "1" * n or s == "1" * n + "0" * n

def step(config, k):
    idx = k - 1
    val = config[idx]
    start = idx
    while start > 0 and config[start-1] == val:
        start -= 1
    end = idx
    while end < len(config) - 1 and config[end+1] == val:
        end += 1
    block = list(config[start:end+1])
    remaining = list(config[:start]) + list(config[end+1:])
    return tuple(block + remaining)

def is_valid_k(n, k):
    configs = []
    for combo in itertools.combinations(range(2*n), n):
        config = [1] * (2*n)
        for i in combo:
            config[i] = 0
        configs.append(tuple(config))

    for config in configs:
        visited = set()
        current = config
        while True:
            if is_good_config(current, n):
                break
            if current in visited:
                return False
            visited.add(current)
            current = step(current, k)
    return True

